#include "../../src/native/ssh/PgpFiles.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <functional>
namespace fs=std::filesystem;
std::string read(fs::path p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
int checks=0;void check(bool v,const char* s){if(!v)throw std::runtime_error(s);std::cout<<"PASS "<<s<<"\n";++checks;}
void denied(std::function<void()> f,const fs::path& output,const char* label){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed&&!fs::exists(output),label);}
int main(int argc,char** argv){try{if(argc!=4)throw std::runtime_error("expected root private public");std::string runtime="C:/ETL/Server/runtime/gnupg/bin/gpg.exe",root=argv[1];auto key=etlforge::pgp::inspect(runtime,root,argv[2]);check(key.hasPrivate,"private key detected");auto pub=etlforge::pgp::inspect(runtime,root,argv[3]);check(!pub.hasPrivate&&pub.fingerprint==key.fingerprint,"public key and fingerprint detected");check(pub.publicKey.find("BEGIN PGP PUBLIC KEY BLOCK")!=std::string::npos,"public export contains no private key");auto input=fs::path(root)/fs::u8path(u8"café 中文.bin"),encrypted=fs::path(root)/"encrypted.pgp",output=fs::path(root)/"output.bin";std::ofstream f(input,std::ios::binary);for(int i=0;i<65536;++i)f.put((char)(i%256));f.close();
 auto transform=[&](const char* material,const std::string& fingerprint,const std::string& pass,fs::path in,fs::path out,bool decrypt,bool armor=false){etlforge::pgp::transform(runtime,root,material,fingerprint,pass,in.u8string(),out.u8string(),decrypt,armor);};
 transform(argv[3],key.fingerprint,"",input,encrypted,false);check(read(encrypted)!=read(input),"target payload encrypted");transform(argv[2],key.fingerprint,"fixture-pass",encrypted,output,true);check(read(input)==read(output),"binary and Unicode filename roundtrip");
 auto armor=fs::path(root)/"armored.asc",clear=fs::path(root)/"armored-clear.bin";transform(argv[3],key.fingerprint,"",input,armor,false,true);check(read(armor).find("BEGIN PGP MESSAGE")!=std::string::npos,"ASCII armored target");transform(argv[2],key.fingerprint,"fixture-pass",armor,clear,true);check(read(clear)==read(input),"armored source roundtrip");
 auto bad=fs::path(root)/"must-not-exist.bin";denied([&]{transform(argv[2],key.fingerprint,"wrong",encrypted,bad,true);},bad,"wrong passphrase produces no output");denied([&]{transform(argv[3],key.fingerprint,"",encrypted,bad,true);},bad,"public-only key cannot decrypt");denied([&]{transform(argv[2],std::string(40,'0'),"fixture-pass",encrypted,bad,true);},bad,"wrong fingerprint rejected");denied([&]{transform(argv[2],key.fingerprint,"fixture-pass",input,bad,true);},bad,"unencrypted input rejected");
 auto damaged=fs::path(root)/"damaged.pgp";auto bytes=read(encrypted);bytes.back()^=1;std::ofstream d(damaged,std::ios::binary);d.write(bytes.data(),bytes.size());d.close();denied([&]{transform(argv[2],key.fingerprint,"fixture-pass",damaged,bad,true);},bad,"tampered ciphertext rejected without partial output");
 auto empty=fs::path(root)/"empty.bin",emptyEncrypted=fs::path(root)/"empty.pgp",emptyClear=fs::path(root)/"empty-clear.bin";std::ofstream(empty,std::ios::binary).close();transform(argv[3],key.fingerprint,"",empty,emptyEncrypted,false);transform(argv[2],key.fingerprint,"fixture-pass",emptyEncrypted,emptyClear,true);check(fs::file_size(emptyClear)==0,"empty file roundtrip");
 bool existing=false;try{transform(argv[3],key.fingerprint,"",input,output,false);}catch(...){existing=true;}check(existing&&read(output)==read(input),"existing output protected");
 bool clean=true;for(auto& entry:fs::directory_iterator(root))if(entry.is_directory()&&entry.path().filename().string().rfind("pgp-",0)==0)clean=false;check(clean,"temporary keyrings removed");std::cout<<"PASSED "<<checks<<"\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
